// Import-script contract: the SQL generated by import-usage-state.mjs from a
// synthetic usage-state.json (produced by scripts/report-usage.mjs), applied to
// D1, must reproduce the numbers report-usage computes from the same state,
// while respecting privacy rules, idempotence, edge card separation, and
// conflict resolution.
import { describe, expect, it } from "vitest";
import { env } from "cloudflare:test";
import { buildStats } from "../src/stats.js";
import { analyticsDayKey } from "../src/util.js";
import { resetStats } from "./helpers.js";
import { ID_D } from "./contract-data.mjs";

const importCase = JSON.parse(env.CONTRACT_IMPORT);

function parseStatements(sql) {
  return sql
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("--"));
}

async function applyImport() {
  await resetStats();
  const statements = parseStatements(importCase.sql);
  expect(statements.length).toBeGreaterThan(0);
  await env.STATS.batch(statements.map((statement) => env.STATS.prepare(statement)));
  return statements;
}

async function snapshotTables() {
  const installs = (await env.STATS.prepare("SELECT * FROM installs ORDER BY install_id").all()).results || [];
  const dailyActive = (await env.STATS.prepare("SELECT * FROM daily_active ORDER BY day, install_id").all()).results || [];
  const counters = (await env.STATS.prepare("SELECT * FROM counters ORDER BY day, kind, key").all()).results || [];
  return { installs, dailyActive, counters };
}

describe("import-usage-state.mjs contract & edge integration", () => {
  it("generated SQL for the synthetic state and excluded test IDs", () => {
    expect(importCase.sql).toContain("INSERT INTO installs");
    expect(importCase.sql).toContain("'pre-edge'");
    expect(importCase.sql).toContain("DELETE FROM counters WHERE day = 'pre-edge'");
    expect(importCase.summary.skippedTestInstalls).toBe(2);
    expect(importCase.summary.droppedDownloadRequests).toBe(2);
    expect(importCase.summary.refsMergedToOther).toBe(2);
  });

  // 1. 导入后安装、首次启动、日活、平台、版本和 report-usage 算的一致（测试安装除外）
  it("1. reproduces report-usage install numbers excluding test/excluded installs", async () => {
    await applyImport();
    const workerStats = await buildStats(env.STATS, importCase.t0);

    const skipped = importCase.summary.skippedTestInstalls;
    expect(workerStats.knownInstallationInstances).toBe(importCase.expected.knownInstallationInstances - skipped);
    expect(workerStats.reportedFirstLaunches).toBe(importCase.expected.reportedFirstLaunches - skipped);
    expect(workerStats.activeInstalls7d).toBe(importCase.expected.activeInstalls7d - skipped);
    expect(workerStats.activeInstalls30d).toBe(importCase.expected.activeInstalls30d - skipped);
    expect(workerStats.dailyActiveInstalls).toBe(importCase.expected.dailyActiveInstalls);

    const expectedPlatforms = { ...importCase.expected.platformInstalls };
    expectedPlatforms.macos = (expectedPlatforms.macos || 0) - skipped;
    expect(workerStats.platformInstalls).toEqual(expectedPlatforms);

    // versionInstalls only tracks live (unfolded) installs in the database
    expect(workerStats.versionInstalls).toEqual({ "0.3.5": 1, "0.3.6": 1 });
  });

  // 2. 导入后 legacy 里的各项和 report-usage 的各类下载请求、文件、渠道、页面访问一致（清洗丢掉的扣除）
  it("2. reproduces legacy download and page view totals after accounting for cleaned entries", async () => {
    await applyImport();
    const workerStats = await buildStats(env.STATS, importCase.t0);
    const legacy = workerStats.legacy;
    expect(legacy).toBeDefined();

    expect(legacy.desktopDownloads).toBe(importCase.expected.totalDesktopDownloadRequests);
    expect(legacy.updateDownloads).toBe(importCase.expected.totalUpdateDownloadRequests);
    expect(legacy.extensionDownloads).toBe(importCase.expected.totalExtensionDownloadRequests);
    expect(legacy.otherDownloads).toBe(
      importCase.expected.totalOtherDownloadRequests - importCase.summary.droppedDownloadRequests
    );
    expect(legacy.pageViews).toBe(importCase.expected.totalPageViews);
    expect(legacy.homePageViews).toBe(importCase.expected.totalHomePageViews);

    // Dropped file (with ..) must not exist in legacy downloadsByFile
    expect(legacy.downloadsByFile["evil..package.zip"]).toBeUndefined();
    // Package files keep their names; anything else (notes.txt here) is
    // summed under the single "other" key instead of being stored verbatim.
    expect(legacy.downloadsByFile["notes.txt"]).toBeUndefined();
    expect(legacy.downloadsByFile.other).toBe(legacy.otherDownloads);
    expect(importCase.summary.otherFileNamesMerged).toBe(1);
    for (const [file, count] of Object.entries(importCase.expected.downloadsByFile)) {
      if (file !== "evil..package.zip" && file !== "notes.txt") {
        expect(legacy.downloadsByFile[file], file).toBe(count);
      }
    }

    // Coverage spans the days that hold legacy data, not the state's
    // coverageStart/updatedAt (both are "now" for this synthetic state):
    // oldest data is ID_F's report 110 days back, newest is ID_G's 2 days back.
    const DAY = 24 * 3600 * 1000;
    expect(legacy.coverageStart).toBe(analyticsDayKey(importCase.t0 - 110 * DAY));
    expect(legacy.coverageEnd).toBe(analyticsDayKey(importCase.t0 - 2 * DAY));
    expect(importCase.summary.coverageEnd).toBe(legacy.coverageEnd);

    // Weird ref (bad ref) was merged into other
    expect(legacy.downloadsByRef["bad ref"]).toBeUndefined();
    expect(legacy.downloadsByRef["other"]).toBe(
      (importCase.expected.downloadsByRef["other"] || 0) + importCase.summary.refsMergedToOther
    );
    for (const [ref, count] of Object.entries(importCase.expected.downloadsByRef)) {
      if (ref !== "bad ref" && ref !== "other") {
        expect(legacy.downloadsByRef[ref], ref).toBe(count);
      }
    }
  });

  // 3. 新卡片总数不受导入影响：先写一批新数据记下 stats.json，再导入，新卡片那些字段不变
  it("3. leaves new edge card totals completely unaffected by legacy import", async () => {
    await resetStats();
    const newDay = "2026-10-30";
    await env.STATS.prepare("INSERT INTO counters (day, kind, key, count) VALUES (?, 'download_file', ?, 5)").bind(newDay, "GravityPort-darwin-arm64-0.3.7.dmg").run();
    await env.STATS.prepare("INSERT INTO counters (day, kind, key, count) VALUES (?, 'download_file', ?, 3)").bind(newDay, "GravityPort-darwin-arm64-0.3.7.zip").run();
    await env.STATS.prepare("INSERT INTO counters (day, kind, key, count) VALUES (?, 'download_ref', ?, 8)").bind(newDay, "bilibili").run();
    await env.STATS.prepare("INSERT INTO counters (day, kind, key, count) VALUES (?, 'page_path', ?, 12)").bind(newDay, "/").run();
    await env.STATS.prepare("INSERT INTO counters (day, kind, key, count) VALUES (?, 'page_path', ?, 6)").bind(newDay, "/en/").run();

    const before = await buildStats(env.STATS, importCase.t0);

    const statements = parseStatements(importCase.sql);
    await env.STATS.batch(statements.map((s) => env.STATS.prepare(s)));

    const after = await buildStats(env.STATS, importCase.t0);

    const NEW_CARD_FIELDS = [
      "downloadsByFile",
      "downloadsByRef",
      "desktopDownloadsByFile",
      "updateDownloadsByFile",
      "extensionDownloadsByFile",
      "totalDownloadRequests",
      "totalDesktopDownloadRequests",
      "totalUpdateDownloadRequests",
      "totalExtensionDownloadRequests",
      "totalOtherDownloadRequests",
      "pageViewsByPath",
      "totalPageViews",
      "totalHomePageViews",
      "homeToDownloadRate",
    ];

    for (const field of NEW_CARD_FIELDS) {
      expect(after[field], field).toEqual(before[field]);
    }
  });

  // 4. 切换期合并：库里先有一个安装 ID（D1 那边 10-29 之后报过），旧状态里同一个 ID 10-28 报过
  //    导入后只有一行，首次是旧的时间、最近是新的时间、版本是新的；同一天两边都有的日活只算一次
  it("4. merges existing post-switchover install with legacy report using conflict rules", async () => {
    // Determine the legacy timestamp for ID_D from a fresh import run
    await applyImport();
    const legacyRow = (await env.STATS.prepare("SELECT * FROM installs WHERE install_id = ?").bind(ID_D).all()).results[0];
    expect(legacyRow).toBeDefined();

    await resetStats();
    const conflictId = ID_D;
    const edgeFirst = legacyRow.last_seen_at + 2 * 24 * 3600 * 1000;
    const edgeLast = legacyRow.last_seen_at + 3 * 24 * 3600 * 1000;

    // Edge has a newer report with version 0.3.9 and first_launch 0
    await env.STATS.prepare(
      "INSERT INTO installs (install_id, first_seen_at, last_seen_at, platform, arch, version, first_launch) " +
        "VALUES (?, ?, ?, 'macos', 'arm64', '0.3.9', 0)"
    ).bind(conflictId, edgeFirst, edgeLast).run();

    const legacyDay = analyticsDayKey(legacyRow.first_seen_at);
    await env.STATS.prepare(
      "INSERT INTO daily_active (day, install_id, first_launch) VALUES (?, ?, 0)"
    ).bind(legacyDay, conflictId).run();

    // Now apply the import where ID_D has older time (legacyRow.first_seen_at) and version 0.3.5, first_launch 1
    const statements = parseStatements(importCase.sql);
    await env.STATS.batch(statements.map((s) => env.STATS.prepare(s)));

    const rows = (await env.STATS.prepare("SELECT * FROM installs WHERE install_id = ?").bind(conflictId).all()).results;
    expect(rows.length).toBe(1);
    const row = rows[0];
    expect(row.first_seen_at).toBe(legacyRow.first_seen_at); // older time wins
    expect(row.last_seen_at).toBe(edgeLast); // newer time wins
    expect(row.version).toBe("0.3.9"); // newer version retained
    expect(row.first_launch).toBe(1); // first_launch is sticky OR

    const activeRows = (await env.STATS.prepare("SELECT * FROM daily_active WHERE day = ? AND install_id = ?").bind(legacyDay, conflictId).all()).results;
    expect(activeRows.length).toBe(1);
    expect(activeRows[0].first_launch).toBe(1);
  });

  // 5. 幂等：同一份 SQL 连续执行 3 次，三张表全部行和执行 1 次完全相同；执行一半再完整跑一次，结果也相同
  it("5. is strictly idempotent across repeated runs and partial reruns", async () => {
    await resetStats();
    const statements = parseStatements(importCase.sql);

    // Run 1
    await env.STATS.batch(statements.map((s) => env.STATS.prepare(s)));
    const snap1 = await snapshotTables();

    // Run 2
    await env.STATS.batch(statements.map((s) => env.STATS.prepare(s)));
    const snap2 = await snapshotTables();
    expect(snap2).toEqual(snap1);

    // Run 3
    await env.STATS.batch(statements.map((s) => env.STATS.prepare(s)));
    const snap3 = await snapshotTables();
    expect(snap3).toEqual(snap1);

    // Partial rerun
    await resetStats();
    const half = statements.slice(0, Math.floor(statements.length / 2));
    await env.STATS.batch(half.map((s) => env.STATS.prepare(s)));
    await env.STATS.batch(statements.map((s) => env.STATS.prepare(s)));
    const snapHalf = await snapshotTables();
    expect(snapHalf).toEqual(snap1);
  });

  // 6. 不带隐私字段：生成的 SQL 和导入后三张表的全部内容里，没有 IPv4/IPv6、Mozilla、contract-test、sources、fileKey、pathHint、headSha256
  it("6. guarantees no privacy fields or state metadata enter SQL or database", async () => {
    await applyImport();
    const snap = await snapshotTables();
    const dbDump = JSON.stringify(snap);
    const sql = importCase.sql;

    const forbiddenPatterns = [
      /\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\b/, // IPv4
      /::1/, // IPv6
      /Mozilla/i,
      /contract-test/,
      /sources/,
      /fileKey/,
      /pathHint/,
      /headSha256/,
      /tailSha256/,
    ];

    for (const pattern of forbiddenPatterns) {
      expect(sql).not.toMatch(pattern);
      expect(dbDump).not.toMatch(pattern);
    }
  });

  // 7. 测试安装 ID 和排除名单里的 ID 不进库
  it("7. excludes test installation IDs and exclude-list IDs from all tables", async () => {
    await applyImport();
    const testInstalls = (await env.STATS.prepare("SELECT * FROM installs WHERE install_id LIKE '00000000-%'").all()).results;
    expect(testInstalls.length).toBe(0);

    const excludedInstalls = (await env.STATS.prepare("SELECT * FROM installs WHERE install_id = ?").bind(importCase.excludedId).all()).results;
    expect(excludedInstalls.length).toBe(0);

    const testActive = (await env.STATS.prepare("SELECT * FROM daily_active WHERE install_id LIKE '00000000-%'").all()).results;
    expect(testActive.length).toBe(0);

    const excludedActive = (await env.STATS.prepare("SELECT * FROM daily_active WHERE install_id = ?").bind(importCase.excludedId).all()).results;
    expect(excludedActive.length).toBe(0);
  });

  // 8. 没导入时 stats.json 没有 legacy 字段，和现在一样
  it("8. leaves legacy field omitted when no import exists", async () => {
    await resetStats();
    await env.STATS.prepare("INSERT INTO counters (day, kind, key, count) VALUES ('2026-10-30', 'page_path', '/', 1)").run();
    const stats = await buildStats(env.STATS, importCase.t0);
    expect(stats.legacy).toBeUndefined();
    expect(stats.migratedFromLegacy).toBe(false);
  });

  it("folded expired installations into cumulative counters and kept recent trend line", async () => {
    await applyImport();
    const installs = (await env.STATS.prepare("SELECT install_id, last_seen_at FROM installs ORDER BY install_id").all()).results;
    // Only live installations (ID_D, ID_G) are rows in installs table
    expect(installs.length).toBe(2);

    const folded = (await env.STATS.prepare("SELECT key, count FROM counters WHERE kind = 'install_total'").all()).results;
    expect(folded).toEqual([{ key: "all", count: 2 }]);
    const firstLaunchFolded = (await env.STATS.prepare("SELECT count FROM counters WHERE kind = 'install_first_launch'").all()).results;
    expect(firstLaunchFolded).toEqual([{ count: 1 }]);

    const stats = await buildStats(env.STATS, importCase.t0);
    expect(stats.migratedFromLegacy).toBe(true);
    const recentDay = analyticsDayKey(importCase.t0 - 3 * 24 * 3600 * 1000);
    const trendRow = stats.daily.find((row) => row.date === recentDay);
    expect(trendRow).toBeTruthy();
    expect(trendRow.pageViews).toBe(20);
    expect(trendRow.homePageViews).toBe(15);
  });
});
